import{_ as a,o as n,a as p,b as l}from"./app.CttuQoSk.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核内同步","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync"},{"text":"TQueSync","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/TQueSync"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/TQueSync.md","filePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/TQueSync.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"id取值范围说明","slug":"id取值范围说明","link":"#id取值范围说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788871572000}'),c={name:"api/SIMD-API/basic_api/sync_control/intra_core_sync/TQueSync.md"};function t(e,s,i,d,o,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>TQueSync</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_block_sync_intf.h&quot;</code>。</p><p>TQueSync类用于核内多流水间的同步。TQueSync类的模板参数用于指定源流水和目标流水，目的流水等待源流水，从而解决多流水间的数据访问依赖。TQueSync类的成员函数SetFlag/WaitFlag接口用于完成具体的同步操作，同一核内不同流水线之间的同步指令，具有数据依赖的不同流水指令之间需要插入此同步。其功能说明如下：</p><ul><li>SetFlag：当前序指令的所有读写操作都完成之后，当前指令开始执行，并将硬件中的对应标志位设置为1。</li><li>WaitFlag：当执行到该指令时，如果发现对应标志位为0，该队列的后续指令将一直被阻塞；如果发现对应标志位为1，则将对应标志位设置为0，同时后续指令开始执行。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>此接口与<a href="SetFlag_WaitFlag_ISASI.html">SetFlag/WaitFlag(ISASI)</a>接口也能实现相同的功能。二者的区别在于，TQueSync类接口可以保证跨硬件版本兼容，而<a href="SetFlag_WaitFlag_ISASI.html">SetFlag/WaitFlag(ISASI)</a>中的接口标注为ISASI类别，不能保证跨硬件版本兼容。</p></div><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="n">TEventID</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="kt">int8_t</span><span class="p">;</span>

<span class="k">template</span><span class="o">&lt;</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">pipe_t</span><span class="w"> </span><span class="n">dst</span><span class="o">&gt;</span>
<span class="k">class</span><span class="w"> </span><span class="nc">TQueSync</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetFlag</span><span class="p">(</span><span class="n">TEventID</span><span class="w"> </span><span class="n">id</span><span class="p">)</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">WaitFlag</span><span class="p">(</span><span class="n">TEventID</span><span class="w"> </span><span class="n">id</span><span class="p">)</span>
<span class="p">};</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 类模板参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>输入</td><td>源流水。支持的流水参考<a href="intra_core_sync_overview.html#%E7%A1%AC%E4%BB%B6%E6%B5%81%E6%B0%B4%E7%B1%BB%E5%9E%8B">硬件流水类型</a>。</td></tr><tr><td>dst</td><td>输入</td><td>目的流水。支持的流水参考<a href="intra_core_sync_overview.html#%E7%A1%AC%E4%BB%B6%E6%B5%81%E6%B0%B4%E7%B1%BB%E5%9E%8B">硬件流水类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 成员函数参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>id</td><td>输入</td><td>事件ID，数据类型为TEventID。推荐通过<a href="../../resource_management/TPipe/AllocEventID.html">AllocEventID</a>或者<a href="../../resource_management/TPipe/FetchEventID.html">FetchEventID</a>来获取。<br>不同产品对id的取值范围说明请参见<a href="#id%E5%8F%96%E5%80%BC%E8%8C%83%E5%9B%B4%E8%AF%B4%E6%98%8E">id取值范围说明</a>。</td></tr></tbody></table><h3 id="id取值范围说明">id取值范围说明<a class="header-anchor" href="#id取值范围说明">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，取值范围是0-7。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，取值范围是0-7。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，取值范围是0-7。</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品，取值范围是0-7。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core，取值范围是0-7。</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品，取值范围是0-3。</li></ul></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p><code>src</code>和<code>dst</code>必须为支持的硬件流水，且二者不能相同。</p></li><li><p>SetFlag只是设置硬件标志位，不会阻塞源流水中的下一个指令。</p></li><li><p>SetFlag和WaitFlag必须成对使用，且模板参数<code>src</code>、<code>dst</code>和输入参数<code>id</code>必须完全一致。如果不匹配，会引发timeout问题。</p></li><li><p>在采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/tpipe_tque_programming/tpipe_tque_paradigm.html">TPipe-TQue框架编程范式</a>时，<code>id</code>需要通过<a href="../../resource_management/TPipe/AllocEventID.html">AllocEventID</a>或者<a href="../../resource_management/TPipe/FetchEventID.html">FetchEventID</a>来获取。</p></li><li><p>在采用<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html">静态Tensor编程范式</a>时，事件类型和<code>id</code>由开发者自行管理，建议使用事件ID0-5，事件ID6用于系统内部规划（当前未使用），事件ID7用于TPipe编程中的<strong>自动同步</strong>功能，目前暂不建议直接使用事件ID6-7。</p></li><li><p>相同源流水、目的流水和<code>id</code>下，连续使用SetFlag会引发未定义行为，此时再执行PipeBarrier&lt;PIPE_ALL&gt;会出现卡死现象：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">TQueSync</span><span class="o">&lt;</span><span class="n">PIPE_M</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">sync</span><span class="p">;</span>
<span class="n">sync</span><span class="p">.</span><span class="n">SetFlag</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">  </span><span class="c1">// 第一次调用SetFlag。</span>
<span class="n">sync</span><span class="p">.</span><span class="n">SetFlag</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span><span class="w">  </span><span class="c1">// 第二次调用SetFlag（相同源流水、目的流水和id连续使用，引发未定义行为）。</span>
<span class="p">...</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span><span class="w">  </span><span class="c1">// 触发卡死。</span>
<span class="p">...</span>
<span class="n">sync</span><span class="p">.</span><span class="n">WaitFlag</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">sync</span><span class="p">.</span><span class="n">WaitFlag</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>如DataCopy需要等待SetValue执行完成后才能执行，需要插入PIPE_S到PIPE_MTE3的同步。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstGlobal</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">;</span>
<span class="n">dstLocal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">TQueSync</span><span class="o">&lt;</span><span class="n">PIPE_S</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="w"> </span><span class="n">sync</span><span class="p">;</span>
<span class="n">sync</span><span class="p">.</span><span class="n">SetFlag</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">sync</span><span class="p">.</span><span class="n">WaitFlag</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">dataSize</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const v=a(c,[["render",t]]);export{_ as __pageData,v as default};
